docker exec startuphafen-devcontainer-maildev-1 node -e '
const net=require("net");
const s=net.connect(1025,"127.0.0.1");
let lines=[],expect="220",step=0;
const seq=["","EHLO validator","MAIL FROM:<test@startuphafen.de>","RCPT TO:<user@example.com>","DATA","From: noreply@startuphafen.de","To: user@example.com","Subject: validation-test","Content-Type: text/plain","","This is a maildev validation email.","",".","QUIT"];
const exps=["220","250","250","250","354","354","354","354","354","354","354","354","354","250","221"];
function tryComplete(){
  const code=lines[0].slice(0,3);
  if(code!==expect) return false;
  const terminal=lines[lines.length-1].slice(3,4)===" ";
  if(!terminal) return false;
  lines=[];
  return true;
}
s.on("data",d=>{
  d.toString().split("\r\n").forEach(l=>{
    if(l==="") return;
    lines.push(l);
    if(tryComplete()){
      if(step>0) console.log(">",seq[step-1].slice(0,40),"->",lines[0]||"done");
      step++;
      if(step>=seq.length){ s.end(); return; }
      expect=exps[step];
      s.write(seq[step]+"\r\n");
    }
  });
});
s.on("end",()=>{ console.log("SMTP SESSION COMPLETE"); process.exit(0); });
setTimeout(()=>{ console.log("TIMEOUT step",step); process.exit(1); },8000);
'

